562	// CandidateView 是一个已登记候选的只读视图。
563	type CandidateView struct {
564		// Round 候选所属轮次。
565		Round uint64
566		// BlockID 候选区块标识。
567		BlockID string
568		// TxIDs 候选中的交易顺序。
569		TxIDs []string
570		// Local 是否为本节点 Propose 产生的本地提议。
