929	// BlockAt 按连续高度查询确认块，高度从 1 开始。
930	func (n *Node) BlockAt(height uint64) (Block, error) {
931		n.mu.Lock()
932		defer n.mu.Unlock()
933		if height == 0 || height > uint64(len(n.st.Blocks)) {
934			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
935		}
936		return copyBlock(&n.st.Blocks[height-1]), nil
937	}
938	
939	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
940	// 返回的是取得时的独立快照，调用方改写不影响节点内的确认历史。
941	func (n *Node) LatestBlock() (Block, bool) {
942		n.mu.Lock()
943		defer n.mu.Unlock()
944		if len(n.st.Blocks) == 0 {
945			return Block{}, false
946		}
947		return copyBlock(&n.st.Blocks[len(n.st.Blocks)-1]), true
948	}
