116				}
117				if fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
118					t.Fatalf("confirming block tx order = %v, want [a1]", res.Block.TxIDs)
119				}
120				if res.Block.PreviousID != "" {
121					t.Fatalf("genesis previous id = %q, want empty", res.Block.PreviousID)
122				}
123	
124				// 立即进入下一轮，确认高度前进；未投票者不阻止确认。
125				if n.CurrentRound() != 2 || n.Height() != 1 {
126					t.Fatalf("after confirm round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
127				}
