520			t.Fatalf("tx still valid in round 2: %v", p2.TxIDs)
521		}
522		// 旧轮次投票不能影响新提议
523		if _, err := n.Vote(keys[0].pub, 1, p2.BlockID); reason(err) != ReasonWrongRound {
524			t.Fatalf("got %v, want wrong-round", err)
525		}
526		if _, err := n.Vote(keys[0].pub, 2, p1.BlockID); reason(err) != ReasonWrongBlock {
527			t.Fatalf("got %v, want wrong-block", err)
528		}
529		// 结束轮次 2 进入轮次 3，tx1 到期
530		n.EndRound()
531		info, _ := n.Tx(tx1.ID())
532		if info.Status != StatusExpired {
533			t.Fatalf("status = %s, want expired", info.Status)
534		}
535		p3, _ := n.Propose()
536		if !p3.Empty {
537			t.Fatalf("expired tx must not be packed: %v", p3.TxIDs)
538		}
539		acct := n.Account(keys[0].pub)
540		if len(acct.Pending) != 0 {
541			t.Fatalf("expired tx must not remain pending: %+v", acct.Pending)
542		}
543	}
544	
545	// 停止再启动恢复全部状态。
546	func TestPersistenceRoundTrip(t *testing.T) {
547		keys := genKeys(t, 4)
548		dir := t.TempDir()
549		vals := make([][]byte, len(keys))
550		for i, k := range keys {
551			vals[i] = k.pub
552		}
553		n, err := New(dir, Config{Seed: []byte("persist-seed"), Validators: vals, MaxTxsPerBlock: 5})
554		if err != nil {
555			t.Fatal(err)
556		}
557		txQ := NewTransaction(keys[0].priv, 2, []byte("gap"), 1, 100) // 缺口，留在池中
558		n.Submit(txQ)
559		tx1 := NewTransaction(keys[1].priv, 1, []byte("a"), 4, 100)
560		n.Submit(tx1)
561		p, _ := n.Propose()
562		n.Vote(keys[0].pub, 1, p.BlockID) // 仅一票，提议与票数未决
563	
564		n2, err := Open(dir)
565		if err != nil {
566			t.Fatal(err)
567		}
568		if n2.CurrentRound() != 1 {
569			t.Fatalf("round restored = %d", n2.CurrentRound())
570		}
571		p2, ok := n2.Proposal()
572		if !ok || p2.BlockID != p.BlockID || len(p2.TxIDs) != len(p.TxIDs) {
573			t.Fatalf("proposal not restored: %+v", p2)
574		}
575		// 重复投票不计数：keys[0] 的票已随状态恢复
576		res, err := n2.Vote(keys[0].pub, 1, p.BlockID)
577		if err != nil || res.Counted {
578			t.Fatalf("restored vote dedup failed: %+v %v", res, err)
579		}
580		// 再补两票即可确认，池内缺口交易仍在
581		res, _ = n2.Vote(keys[1].pub, 1, p.BlockID)
582		res, _ = n2.Vote(keys[2].pub, 1, p.BlockID)
583		if !res.Confirmed {
584			t.Fatal("restored node should reach confirmation")
585		}
586		acct := n2.Account(keys[0].pub)
587		if acct.Gap != 1 || len(acct.Pending) != 1 || acct.Pending[0].ID != txQ.ID() {
588			t.Fatalf("pool not restored: %+v", acct)
589		}
590		// 确认历史与账户序号
591		b, _ := n2.BlockAt(1)
592		if b.ID != p.BlockID {
593			t.Fatal("history not restored")
594		}
595		if a := n2.Account(keys[1].pub); a.ConfirmedSequence != 1 {
596			t.Fatalf("confirmed seq restored = %d", a.ConfirmedSequence)
597		}
598	
599		// New 拒绝覆盖已有状态目录
600		if _, err := New(dir, Config{Seed: []byte("persist-seed"), Validators: vals, MaxTxsPerBlock: 5}); err == nil {
601			t.Fatal("New over existing state must fail")
602		}
603	}
604	
605	// 确定性：相同种子、初始配置与输入顺序，产生相同提议者、交易顺序、区块标识与确认历史。
606	func TestDeterminism(t *testing.T) {
607		keys := genKeys(t, 4)
608		build := func() ([]string, []Block, []byte, uint64) {
609			dir := t.TempDir()
610			vals := make([][]byte, len(keys))
611			for i, k := range keys {
612				vals[i] = append([]byte(nil), k.pub...)
613			}
614			n, err := New(dir, Config{Seed: []byte("determinism-seed"), Validators: vals, MaxTxsPerBlock: 3})
615			if err != nil {
616				t.Fatal(err)
617			}
618			var proposers []byte
619			for r := 1; r <= 3; r++ {
620				proposers = append(proposers, n.CurrentProposer()...)
621				// 固定的输入顺序
622				n.Submit(NewTransaction(keys[r%4].priv, uint64(r), []byte(fmt.Sprintf("c%d", r)), uint64((r*7)%13), 100))
623				n.Submit(NewTransaction(keys[(r+1)%4].priv, 1, []byte(fmt.Sprintf("d%d", r)), uint64(r), 100))
624				p, _ := n.Propose()
625				confirmByVotes(t, n, keys, p.BlockID)
626			}
627			var ids []string
628			for _, b := range n.st2Blocks() {
629				ids = append(ids, b.ID)
630			}
631			return ids, n.st2Blocks(), proposers, n.CurrentRound()
632		}
633		ids1, blocks1, prop1, round1 := build()
634		ids2, blocks2, prop2, round2 := build()
635		if fmt.Sprint(ids1) != fmt.Sprint(ids2) {
636			t.Fatalf("block ids differ:\n%v\n%v", ids1, ids2)
637		}
638		if string(prop1) != string(prop2) {
639			t.Fatal("proposers differ")
640		}
641		if round1 != round2 {
642			t.Fatal("rounds differ")
643		}
644		for i := range blocks1 {
645			if fmt.Sprint(blocks1[i].TxIDs) != fmt.Sprint(blocks2[i].TxIDs) {
646				t.Fatalf("tx order differs in block %d", i+1)
647			}
648		}
649	}
650	
651	// st2Blocks 是测试辅助：导出全部确认块。
652	func (n *Node) st2Blocks() []Block {
653		out := make([]Block, len(n.st.Blocks))
654		copy(out, n.st.Blocks)
655		return out
656	}
657	
658	// 提议者可查询且在名单内；同轮可复算。
659	func TestProposerQuery(t *testing.T) {
660		keys := genKeys(t, 4)
661		n, _ := newTestNode(t, keys, 10)
662		p := n.CurrentProposer()
663		found := false
664		for _, k := range keys {
665			if string(k.pub) == string(p) {
666				found = true
667			}
668		}
669		if !found {
670			t.Fatal("proposer not in validator set")
671		}
672		if string(n.ProposerFor(1)) != string(p) {
673			t.Fatal("ProposerFor(1) must equal current proposer")
674		}
675	}
676	
677	// 写入失败时一次确认不生效：内存保持确认前状态，磁盘也仍是确认前文件，
678	// 恢复后只能看到确认前的完整状态。
679	func TestConfirmAtomicityOnWriteFailure(t *testing.T) {
680		keys := genKeys(t, 4)
681		n, dir := newTestNode(t, keys, 10)
682		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
683		n.Submit(tx1)
684		p, _ := n.Propose()
685		// 已有 1 票的状态先落盘
686		if _, err := n.Vote(keys[0].pub, 1, p.BlockID); err != nil {
687			t.Fatal(err)
688		}
689		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
690		if err != nil {
691			t.Fatal(err)
692		}
693	
694		// 注入写入失败：决定性的第三票必须报错，且状态保持确认前。
695		n.injectSaveErr = errors.New("disk full (simulated)")
696		res, err := n.Vote(keys[1].pub, 1, p.BlockID)
697		if err == nil {
698			t.Fatal("expected save error")
699		}
700		if res != nil {
701			t.Fatalf("result should be nil on error, got %+v", res)
702		}
703		n.injectSaveErr = nil
704	
705		if n.Height() != 0 || n.CurrentRound() != 1 {
706			t.Fatalf("in-memory state changed despite failed write: height=%d round=%d", n.Height(), n.CurrentRound())
707		}
708		pp, ok := n.Proposal()
709		if !ok || pp.BlockID != p.BlockID {
710			t.Fatal("proposal must survive the failed confirmation")
711		}
712		info, _ := n.Tx(tx1.ID())
713		if info.Status != StatusProposed {
714			t.Fatalf("tx status = %s, want proposed (pre-confirmation state)", info.Status)
715		}
716		// 磁盘文件仍是确认前内容
717		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
718		if err != nil {
719			t.Fatal(err)
720		}
721		if string(before) != string(after) {
722			t.Fatal("state file changed despite failed write")
723		}
724		// 模拟“中途停止后恢复”：Open 出来的也只能是确认前状态
725		reopened, err := Open(dir)
726		if err != nil {
727			t.Fatal(err)
728		}
729		if reopened.Height() != 0 || reopened.CurrentRound() != 1 {
730			t.Fatal("reopened node should show pre-confirmation state")
731		}
732		// keys[1] 那次投票没有计入，仍需两票才能确认
733		r2, err := reopened.Vote(keys[1].pub, 1, p.BlockID)
734		if err != nil || r2.Confirmed {
735			t.Fatalf("first post-reopen vote: %+v %v", r2, err)
736		}
737		r3, err := reopened.Vote(keys[2].pub, 1, p.BlockID)
738		if err != nil || !r3.Confirmed {
739			t.Fatalf("second post-reopen vote should confirm: %+v %v", r3, err)
740		}
741		if reopened.Height() != 1 {
742			t.Fatal("confirmation should now be durable")
743		}
744	}
745	
746	// 保存文件形态检查：状态目录下只有 state.json（临时文件已收尾）。
747	func TestStateFileLayout(t *testing.T) {
748		keys := genKeys(t, 4)
749		dir := t.TempDir()
750		vals := [][]byte{keys[0].pub, keys[1].pub, keys[2].pub}
751		n, err := New(filepath.Join(dir, "node"), Config{Seed: []byte("x"), Validators: vals, MaxTxsPerBlock: 2})
752		if err != nil {
753			t.Fatal(err)
754		}
755		n.Submit(NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100))
756		p, _ := n.Propose()
757		n.Vote(keys[0].pub, 1, p.BlockID)
758		entries, err := os.ReadDir(filepath.Join(dir, "node"))
759		if err != nil {
760			t.Fatal(err)
761		}
762		var names []string
763		for _, e := range entries {
764			names = append(names, e.Name())
765		}
766		if fmt.Sprint(names) != "[state.json]" {
767			t.Fatalf("unexpected files: %v", names)
768		}
769	}
